from fastapi.responses import HTMLResponse
from . import fast_scalper_beta_001_legacy as legacy

HTML=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta http-equiv="Cache-Control" content="no-store"><title>Fast Scalper Beta</title><style>*{box-sizing:border-box}html,body{margin:0;background:#080e1b;color:#edf2ff;font-family:Arial,Helvetica,sans-serif}body{min-width:320px}.wrap{max-width:720px;margin:auto;padding:10px 25px 30px}.head{margin:0 0 15px}.brand{display:flex;align-items:flex-start;gap:8px}.bolt{font-size:47px;line-height:.9}.brand h1{margin:0;font-size:35px;font-weight:800;line-height:1.03;letter-spacing:-.7px}.sub{margin-top:7px;color:#8d98b1;font-size:18px;white-space:nowrap}.card{background:#111a2d;border:1px solid #273653;border-radius:24px;padding:18px 25px;margin-bottom:15px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:14px}.metric{background:#0a1223;border-radius:17px;padding:15px 18px;min-height:91px}.k{font-size:20px;line-height:1.05;color:#d8e0f1}.v{font-size:29px;font-weight:800;margin-top:5px;white-space:nowrap}.unit{font-size:16px;color:#91a0ba;font-weight:400;margin-left:6px}.modes{display:grid;grid-template-columns:1fr 1fr 1.08fr;gap:12px;margin-top:15px}.btn{height:57px;border:0;border-radius:15px;color:#fff;background:#245b91;font-size:17px;font-weight:800;padding:0 10px;cursor:pointer;white-space:nowrap}.paper{background:#293954}.green{background:#00a65a}.red{background:#c52f47}.gray{background:#293954}.note{margin-top:10px;color:#9ba5ba;font-size:17px}.controls{padding:20px 25px 19px}.controlRow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.04fr);gap:14px;align-items:end}.controlRow+.controlRow{margin-top:14px}.label{font-size:13px;color:#8d98b1;font-weight:800;margin:0 0 6px}.input{height:54px;width:100%;background:#091122;border:1px solid #30405e;border-radius:15px;color:#edf2ff;padding:0 16px;font-size:20px;outline:none}.input::placeholder{color:#7e8798}.profitRow{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:end;margin-top:14px}.check{height:54px;display:flex;align-items:center;gap:9px;font-size:20px;white-space:nowrap}.check input{width:27px;height:27px;accent-color:#1676e8}.actions{display:grid;grid-template-columns:1.3fr 1fr .72fr;gap:10px;margin-top:14px}.actions .btn{height:57px}.off{display:flex;align-items:center;gap:14px;margin-top:12px}.off .btn{width:147px}.session{color:#9ba5ba;font-size:18px;white-space:nowrap}.status{color:#9ba5ba;font-size:14px;min-height:17px;margin-top:5px}.title{font-size:38px;font-weight:800;margin:0 0 14px;letter-spacing:-.5px}.badge{display:inline-block;background:#c52f47;border-radius:14px;padding:7px 13px;font-size:13px;font-weight:800;margin-bottom:12px}.empty{color:#8d96a9;font-size:18px}.pos{display:flex;flex-direction:column}.pitem{font-size:16px;color:#c8d2e7;padding:10px 4px;border-bottom:1px solid #30405e}.slots{display:grid;grid-template-columns:1fr 1fr;gap:10px}.slot{height:48px;background:#091122;border:1px solid #30405e;border-radius:13px;color:#edf2ff;padding:0 14px;font-size:16px;width:100%}@media(max-width:470px){.wrap{padding:8px 18px 25px}.brand{gap:6px}.bolt{font-size:39px}.brand h1{font-size:31px}.sub{font-size:16px}.card{padding:16px 16px;margin-bottom:12px}.stats{gap:8px}.metric{padding:12px;min-height:78px}.k{font-size:17px}.v{font-size:25px}.unit{font-size:14px}.modes{gap:7px;margin-top:11px}.modes .btn{height:50px;font-size:14px;padding:0 5px}.note{font-size:15px}.controls{padding:17px 16px}.controlRow{gap:8px}.controlRow+.controlRow,.profitRow{margin-top:10px}.label{font-size:10px}.input{height:47px;padding:0 10px;font-size:18px}.controlRow .btn{height:47px;font-size:13px;padding:0 5px}.check{height:47px;font-size:16px;gap:7px}.check input{width:22px;height:22px}.actions{gap:7px;margin-top:10px}.actions .btn{height:50px;font-size:13px;padding:0 5px}.off{gap:8px;margin-top:8px}.off .btn{width:115px;height:47px;font-size:14px}.session{font-size:14px}.title{font-size:31px}.empty{font-size:17px}.pitem{font-size:15px}.slot{height:45px;font-size:15px}}</style></head><body><div class="wrap"><header class="head"><div class="brand"><span class="bolt">⚡</span><div><h1>Fast Scalper Beta</h1><div class="sub">Version 0.01 REPAIR PAPER · Trading TF: 3m</div></div></div></header><section class="card"><div class="stats"><div class="metric"><div class="k">Account Balance</div><div class="v"><span id="account">1850.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Bot Balance</div><div class="v"><span id="bot">0.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Reserve</div><div class="v"><span id="reserve">0.0000</span> <span class="unit">USDT</span></div></div><div class="metric"><div class="k">Session PnL</div><div class="v"><span id="pnl">0.0000</span> <span class="unit">USDT</span></div></div></div><div class="modes"><button class="btn paper" onclick="setMode('PAPER')">PAPER</button><button class="btn" onclick="setMode('BINANCE_TEST')">BINANCE<br>TEST</button><button class="btn" onclick="testBinance()">TEST BINANCE</button></div><div class="note" id="note">Bot balance set: 0.0000 USDT</div></section><section class="card controls"><div class="controlRow"><div><div class="label">BOT BALANCE · USDT</div><input id="allocation" class="input" inputmode="decimal" value="150" aria-label="Bot balance"></div><button class="btn" onclick="setAllocation()">SET BOT BALANCE</button></div><div class="controlRow"><div><div class="label">WITHDRAW AMOUNT · USDT</div><input id="withdraw" class="input" inputmode="decimal" value="0.00" aria-label="Withdraw amount"></div><button class="btn red" onclick="doWithdraw()">WITHDRAW</button></div><div class="profitRow"><div><div class="label">PROFIT TARGET · %</div><input id="profit" class="input" inputmode="decimal" value="0.33" aria-label="Profit Target"></div><label class="check"><input id="reinvest" type="checkbox" checked> Reinvest</label></div><div class="actions"><button class="btn green" onclick="startBot()">BOT ON · ACTIVE</button><button class="btn red" onclick="emergencyStop()">EMERGENCY</button><button class="btn gray" onclick="resetBot()">RESET</button></div><div class="off"><button class="btn red" onclick="stopBot()">BOT OFF</button><div class="session" id="session">SESSION 00:00 · 24H 00:00</div></div><div class="status" id="status"></div></section><section class="card"><div class="title">Open Positions</div><div id="badge" class="badge">BOT OFF · TRADING STOPPED</div><div class="pos" id="positions"><div class="empty">No open positions</div></div></section><section class="card"><div class="title">Rotation Pool · TOP-20</div><div class="slots" id="slots"></div></section></div><script>const $=id=>document.getElementById(id),num=x=>Number(x||0).toFixed(4),age=s=>{s=Math.max(0,Math.floor(Number(s||0)));return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},api=async(p,o={})=>{const r=await fetch(p,{cache:'no-store',headers:{'Content-Type':'application/json',...(o.headers||{})},...o});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||d.error||('HTTP '+r.status));return d},msg=t=>{$('status').textContent=t||''};async function refresh(){try{const s=await api('/api/state');$('account').textContent=num(s.account);$('bot').textContent=num(s.bot_balance);$('reserve').textContent=num(s.reserve);$('pnl').textContent=num(s.session_realized);$('profit').value=Number(s.profit_pct??.33).toFixed(2);$('reinvest').checked=!!s.reinvest;$('session').textContent='SESSION '+age(s.session_age)+' · 24H '+age(s.day_age);$('note').textContent='Bot balance set: '+num(s.bot_balance)+' USDT';$('badge').textContent=s.running?'BOT ON · ACTIVE':'BOT OFF · TRADING STOPPED';renderSlots(s.slots||[]);renderPositions(s.positions||[]);if(s.error)msg(s.error)}catch(e){msg(e.message)}}function renderSlots(a){const el=$('slots');if(el.children.length===20){[...el.children].forEach((x,i)=>{if(document.activeElement!==x)x.value=a[i]||''});return}el.innerHTML='';for(let i=0;i<20;i++){const x=document.createElement('input');x.className='slot';x.placeholder='USDT pair';x.addEventListener('change',saveSlots);el.appendChild(x)}[...el.children].forEach((x,i)=>x.value=a[i]||'')}let timer;function saveSlots(){clearTimeout(timer);timer=setTimeout(async()=>{try{const a=[...document.querySelectorAll('.slot')].map(x=>x.value.trim().toUpperCase()).filter(Boolean);await api('/api/slots',{method:'POST',body:JSON.stringify({slots:a,profit_pct:Number($('profit').value.replace(',','.'))||.33,reinvest:$('reinvest').checked})});msg('Rotation Pool saved')}catch(e){msg(e.message)}},250)}function renderPositions(a){const el=$('positions');if(!a.length){el.innerHTML='<div class="empty">No open positions</div>';return}el.innerHTML=a.map(p=>'<div class="pitem"><b>'+p.symbol+'</b> · '+num(p.stake)+' USDT · '+age(p.age_seconds)+' · TIMEOUT ARMED · …</div>').join('')}async function setMode(m){try{await api('/api/mode',{method:'POST',body:JSON.stringify({mode:m})});msg('Mode set: '+m);await refresh()}catch(e){msg(e.message)}}async function testBinance(){try{const d=await api('/api/test-binance',{method:'POST'});msg(d.message||'Binance Testnet connection OK')}catch(e){msg(e.message)}}async function setAllocation(){try{const amount=Number($('allocation').value.replace(',','.'));if(!(amount>=0))throw Error('Enter a valid Bot Balance');await api('/api/allocation',{method:'POST',body:JSON.stringify({amount})});msg('Bot balance set');await refresh()}catch(e){msg(e.message)}}async function doWithdraw(){try{const amount=Number($('withdraw').value.replace(',','.'));if(!(amount>0))throw Error('Enter a withdrawal amount');await api('/api/withdraw',{method:'POST',body:JSON.stringify({amount})});$('withdraw').value='0.00';msg('Withdraw completed');await refresh()}catch(e){msg(e.message)}}async function startBot(){try{const profit=Number($('profit').value.replace(',','.'));await api('/api/paper/start',{method:'POST',body:JSON.stringify({profit_pct:Number.isFinite(profit)?profit:.33,reinvest:$('reinvest').checked})});msg('Bot active');await refresh()}catch(e){msg(e.message)}}async function stopBot(){try{await api('/api/paper/stop',{method:'POST'});msg('Bot OFF — new entries stopped');await refresh()}catch(e){msg(e.message)}}async function emergencyStop(){try{await api('/api/paper/emergency',{method:'POST'});msg('Emergency stop completed');await refresh()}catch(e){msg(e.message)}}async function resetBot(){try{await api('/api/reset',{method:'POST'});msg('Reset completed');await refresh()}catch(e){msg(e.message)}}refresh();setInterval(refresh,1000);</script></body></html>'''

for r in list(legacy.app.router.routes):
    if getattr(r,'path',None)=='/' and 'GET' in (getattr(r,'methods',set()) or set()): legacy.app.router.routes.remove(r)
